select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%aircall.io%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents vocaux IA de la plateforme téléphonique française Aircall qui passent et traitent vos appels professionnels 24h/24, qualifient les leads, envoient des rappels, confirment les rendez-vous et routent les appels.', 'AI voice agents from French phone platform Aircall that place and handle business calls 24/7, qualify leads, send reminders, confirm appointments and route calls.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%ringover.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent vocal IA conversationnel de l''opérateur téléphonique français Ringover qui répond à vos appels 24h/24, qualifie les leads, planifie les rendez-vous et se synchronise avec vos outils métier.', 'Conversational AI voice agent from French telephony provider Ringover that answers calls 24/7, qualifies leads, schedules appointments and syncs with business tools.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%waalaxy.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent de prospection LinkedIn qui définit vos cibles à partir de votre site, source les prospects, rédige des messages personnalisés, gère les réponses et prend les rendez-vous, avec un mode autopilote.', 'LinkedIn outreach agent that picks targets from your website, sources prospects, writes personalized messages, handles replies and books meetings, with optional autopilot.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%lemlist.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent de prospection conversationnel intégré à lemlist qui trouve des leads, rédige campagnes multicanales et réponses, analyse les résultats et gère les données CRM, avec validation avant lancement.', 'Conversational prospecting agent inside lemlist that finds leads, drafts multichannel campaigns and replies, analyzes results and manages CRM data, with approval before launch.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%noota.io%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'IA de réunion française dotée d''un agent de recrutement en option (Taalent) pour les équipes de recrutement, ainsi que d''un agent email, de la transcription, des résumés et des notes prêtes pour CRM/ATS.', 'French meeting AI with a recruitment agent add-on (Taalent) for hiring teams, alongside an email agent, transcription, summaries and CRM/ATS-ready notes.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%modjo.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Bibliothèque de plus de 15 agents IA commerciaux exploitant vos appels, deals et données CRM pour préparer les commerciaux, rédiger les relances, résumer les deals, coacher et détecter churn et deals perdus.', 'Library of 15+ AI sales agents built on call, deal and CRM data that prep reps, draft follow-ups, brief deals, coach and flag churn or lost-deal patterns.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%claap.io%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Enregistreur d''appels et agent IA pour les équipes commerciales qui résume vos réunions, complète automatiquement le CRM, rédige les e-mails de relance et ouvre vos données d''appels aux agents IA via MCP.', 'AI call recorder and agent for revenue teams that summarizes meetings, auto-completes CRM fields, drafts follow-up emails and lets AI agents query call data via MCP.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%phacetlabs.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents IA pour les équipes finance qui extraient les données de factures, effectuent le rapprochement à trois voies avec bons de commande et réceptions, automatisent le rapprochement bancaire et signalent les écarts.', 'AI agents for finance teams that extract invoice data, run 3-way matching against POs and receipts, automate bank reconciliation and flag discrepancies.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%jimini.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'IA juridique française pour cabinets et directions juridiques qui automatise la recherche juridique, l''analyse de contrats et de documents, la rédaction, la relecture et la traduction, avec agents et workflows juridiques.', 'French legal AI for law firms and in-house teams that automates legal research, contract and document analysis, drafting, proofreading and translation, with legal agents and workflows.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%twin.so%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme no-code où vous décrivez une tâche récurrente en langage naturel et Twin crée des agents qui utilisent vos applications, automatisent le navigateur, appellent des API et s''exécutent selon un planning.', 'No-code platform where you describe recurring work in plain English and Twin builds agents that use your apps, automate browsers, call APIs and run on schedules.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%fr.custplace.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent IA pour les réseaux multi-sites qui répond aux avis en ligne 24h/24 en mode autopilote ou copilote, maintient la cohérence des fiches locales et publie des posts locaux.', 'AI agent for multi-location networks that replies to online reviews 24/7 in autopilot or copilot mode, keeps local listings consistent and publishes local posts.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%langdock.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Espace de travail IA allemand pour entreprises où les équipes créent des agents qui agissent dans Outlook, Jira, Slack ou HubSpot via connecteurs et MCP, avec des workflows automatisés.', 'German enterprise AI workspace where teams build agents that act in tools like Outlook, Jira, Slack and HubSpot via connectors and MCP, plus automated workflows.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%moin.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme de chatbot et d''agents IA conçue à Hambourg pour le service client, qui répond aux demandes sur le site et les messageries et exécute de bout en bout des processus de service prédéfinis.', 'Hamburg-built AI chatbot and agent platform for customer service that answers website and messaging inquiries and runs predefined service processes end to end.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%superchat.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent IA pour WhatsApp, chat web et e-mail qui répond aux clients, qualifie les leads, prend des rendez-vous et crée des tickets via les intégrations CRM et agenda.', 'AI agent for WhatsApp, web chat and email that answers customers, qualifies leads, books appointments and creates tickets via CRM and calendar integrations.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%candis.io%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Automatisation IA de la comptabilité fournisseurs pour les PME allemandes : capture les données des factures, pré-impute comptes et centres de coûts, vérifie la TVA et relance les validations dans Slack et Teams.', 'AI accounts-payable automation for German SMBs that captures invoice data, pre-codes G/L accounts and cost centers, checks VAT compliance and chases approvals in Slack and Teams.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%synthflow.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme d''IA vocale berlinoise dont les agents gèrent les appels entrants et sortants : prise de rendez-vous, qualification des leads, routage des appels et FAQ, avec intégrations CRM.', 'Berlin voice AI platform whose agents handle inbound and outbound phone calls, booking appointments, qualifying leads, routing calls and answering FAQs with CRM integrations.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%famulor.io%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme allemande d''assistant téléphonique IA pour PME et agences qui répond aux appels et en passe, prend des rendez-vous et exécute des actions en cours d''appel, avec API REST et serveur MCP.', 'German AI phone assistant platform for SMBs and agencies that answers and places calls, books appointments and runs mid-call actions, with REST API and MCP server.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%flank.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents juridiques autonomes pour les directions juridiques : ils reçoivent les demandes par e-mail, Teams ou Slack, rédigent et annotent les contrats, négocient et répondent aux questions de conformité.', 'Autonomous legal agents for in-house legal teams that take requests via email, Teams or Slack, draft and redline contracts, negotiate and answer compliance questions.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%workist.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents IA pour grossistes et industriels B2B qui lisent les commandes et demandes de devis reçues par e-mail ou PDF, les valident avec les données de base de l''ERP et les saisissent dans SAP et autres ERP.', 'AI agents for B2B wholesalers and manufacturers that read orders and quote requests from emails and PDFs, validate them against ERP master data and enter them into SAP and other ERPs.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%telli.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme d''agents vocaux IA qui appellent les clients et leur répondent pour qualifier les leads, planifier des rendez-vous, envoyer des rappels et recouvrer les paiements, avec composeur intégré et synchronisation CRM.', 'AI voice agent platform that calls and answers customers to qualify leads, schedule appointments, send reminders and collect payments, with built-in dialer and CRM sync.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%norman.finance%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent comptable IA pour freelances, UG et GmbH allemandes qui catégorise les transactions bancaires, rapproche les justificatifs, prépare les déclarations de TVA et les comptes annuels, avec accès API et MCP.', 'AI bookkeeping agent for German freelancers, UGs and GmbHs that categorizes bank transactions, matches receipts, prepares VAT returns and annual filings, with API and MCP access.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%hypatos.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Main-d''œuvre d''agents IA pour back-offices financiers et centres de services partagés, qui lit factures et documents, agit dans SAP ou Coupa et automatise de bout en bout la comptabilité fournisseurs.', 'Agentic AI workforce for finance back offices and shared services that reads invoices and documents, calls tools in SAP or Coupa and automates accounts-payable transactions end to end.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%getmika.de%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Service comptable IA pour GmbH et UG allemandes qui comptabilise automatiquement les transactions, dépose les déclarations de TVA mensuelles via ELSTER et prépare les comptes annuels, avec revue des cas complexes par des comptables.', 'AI accounting service for German GmbHs and UGs that books transactions automatically, files monthly VAT returns via ELSTER and prepares annual accounts, with accountants reviewing edge cases.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%beamon.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Assistant IA juridique de BRYTER doté d''un mode agentique qui planifie des tâches juridiques en plusieurs étapes, analyse des lots de documents, en extrait les données, effectue des recherches et rédige de longs mémoires.', 'Legal AI assistant from BRYTER with an agentic mode that plans multi-step legal tasks, reviews and extracts data from document sets, researches and drafts long briefs.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%beam.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme d''automatisation agentique pour entreprises dont les agents IA exécutent des workflows en plusieurs étapes : rapprochement factures/bons de commande et saisie SAP, rapprochement bancaire, tri de CV et service client.', 'Agentic automation platform for enterprises whose AI agents run multi-step workflows such as invoice-to-PO matching and SAP posting, bank reconciliation, CV screening and customer service.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%tldv.io%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent IA de réunion pour Zoom, Google Meet et Teams qui enregistre, transcrit et résume les appels, consigne notes et résultats dans le CRM et rédige les e-mails de suivi.', 'AI meeting agent for Zoom, Google Meet and Teams that records, transcribes and summarizes calls, logs notes and outcomes to the CRM and drafts follow-up emails.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%indigo.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme italienne d''agents IA chat et voix pour les entreprises, qui traitent appels et conversations clients 24h/24, agissent dans le CRM/ERP, qualifient les leads et ouvrent des tickets.', 'Italian enterprise platform for chat and voice AI agents that handle customer calls and chats 24/7, act in CRM/ERP systems, qualify leads and open tickets.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%lexroom.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'IA juridique italienne pour cabinets d''avocats et juristes d''entreprise, qui répond aux questions juridiques avec sources citées, analyse les contrats et rédige des documents dans Word.', 'Italian legal AI for law firms and in-house teams that answers legal questions with cited sources, reviews contracts for risky clauses and drafts documents in Word.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%userbot.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme IA italienne pour entreprises, avec agents et workflows qui exploitent vos documents et systèmes (CRM, ERP) et servent vos clients sur WhatsApp, téléphone, e-mail et chat web.', 'Italian enterprise AI platform with agents and workflows that work on company documents and systems (CRM, ERP) and serve customers on WhatsApp, phone, email and web chat.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%spoki.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent IA WhatsApp Business pour PME et e-commerce, qui qualifie les leads, répond aux questions produits, relance les paniers abandonnés et conclut les commandes dans le chat, avec relais humain.', 'WhatsApp Business AI agent for SMBs and e-commerce that qualifies leads, answers product questions, recovers abandoned carts and closes orders in chat, with human handoff.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%equixly.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme de sécurité offensive agentique qui exécute en continu des tests d''intrusion pilotés par IA sur vos API et applications pour détecter les failles d''authentification, d''autorisation et de logique métier.', 'Agentic offensive security platform that continuously runs AI-driven penetration tests on APIs and apps to find auth, authorization and business-logic flaws.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%knowlee.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Système d''exploitation milanais pour agents IA : des SDR IA qui trouvent des leads, prennent des rendez-vous et relancent, et des recruteurs IA qui sourcent et présélectionnent les candidats, avec validation humaine.', 'Milan-built operating system for AI agents: AI SDRs that find leads, book meetings and follow up, and AI recruiters that source and screen candidates, with human approval.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%textyess.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents IA pour marques e-commerce, qui planifient et envoient campagnes et flows WhatsApp et e-mail, et répondent aux questions commandes et produits sur WhatsApp, le site et par téléphone.', 'AI agents for e-commerce brands that plan and send WhatsApp and email campaigns and flows, and answer order and product questions on WhatsApp, web and phone.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%tiledesk.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme open source no-code du sud de l''Italie pour créer des agents IA multicanaux qui automatisent le support client et les processus métier, avec RAG, MCP et relais humain.', 'Open-source no-code platform from southern Italy to build multichannel AI agents that automate customer support and business processes, with RAG, MCP and human handoff.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%domyn.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent de données pour entreprises de Domyn (ex-iGenius, Milan), qui répond aux questions métier sur vos données et le web, surveille les indicateurs, envoie des alertes et analyse les causes.', 'Enterprise data agent from Milan''s Domyn (ex-iGenius) that answers business questions over company data and the web, monitors metrics, sends alerts and runs root-cause analysis.');

select refresh_rankings();

-- Check: the new agents, with their page and French description
select e.name, e.slug as page, (t.value is not null) as french from entities e left join entity_i18n t on t.entity_id = e.id and t.lang = 'fr'
 where e.type = 'agent' and e.website ilike any (array['%aircall.io%', '%ringover.com%', '%waalaxy.com%', '%lemlist.com%', '%noota.io%', '%modjo.ai%', '%claap.io%', '%phacetlabs.com%', '%jimini.ai%', '%twin.so%', '%fr.custplace.com%', '%langdock.com%', '%moin.ai%', '%superchat.com%', '%candis.io%', '%synthflow.ai%', '%famulor.io%', '%flank.ai%', '%workist.com%', '%telli.com%', '%norman.finance%', '%hypatos.ai%', '%getmika.de%', '%beamon.ai%', '%beam.ai%', '%tldv.io%', '%indigo.ai%', '%lexroom.ai%', '%userbot.ai%', '%spoki.com%', '%equixly.com%', '%knowlee.ai%', '%textyess.com%', '%tiledesk.com%', '%domyn.com%']) order by e.name;
